#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for square matrix multiplication using shared memory and tiling.
// This implementation aims for coalesced memory access and reduced global memory traffic.
__global__ void square_matrix_mul_kernel(const float* A, const float* B, float* C, int N) {
    // Define the tile size for shared memory. A common choice for square matrices.
    const int TILE_SIZE = 32; 

    // Declare shared memory for tiles of A and B. 
    // This reduces global memory accesses and improves data locality.
    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE];

    // Calculate the global row and column for the current thread.
    // Each thread computes one element of the output matrix C.
    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    // Accumulator for the C element. Stored in a register for fast access.
    float Cvalue = 0;

    // Loop over tiles of the input matrices.
    // (N + TILE_SIZE - 1) / TILE_SIZE gives the number of tiles needed to cover N elements.
    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; ++tile) {
        // Load A tile into shared memory (sA).
        // Ensure valid memory access within matrix bounds and pad with zeros if out of bounds.
        if (row < N && (tile * TILE_SIZE + threadIdx.x) < N) {
            sA[threadIdx.y][threadIdx.x] = A[row * N + (tile * TILE_SIZE + threadIdx.x)];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f; // Padding for out-of-bounds access
        }

        // Load B tile into shared memory (sB).
        // Similar to A, ensure valid access and pad with zeros.
        if (col < N && (tile * TILE_SIZE + threadIdx.y) < N) {
            sB[threadIdx.y][threadIdx.x] = B[(tile * TILE_SIZE + threadIdx.y) * N + col];
        } else {
            sB[threadIdx.y][threadIdx.x] = 0.0f; // Padding for out-of-bounds access
        }

        // Synchronize threads to ensure all shared memory loads are complete before computation.
        __syncthreads();

        // Perform computation on the loaded tiles (dot product).
        // This loop operates on data entirely within shared memory, optimizing performance.
        for (int k = 0; k < TILE_SIZE; ++k) {
            Cvalue += sA[threadIdx.y][k] * sB[k][threadIdx.x];
        }

        // Synchronize threads again before the next tile iteration.
        __syncthreads();
    }

    // Write the computed Cvalue to global memory if within matrix bounds.
    if (row < N && col < N) {
        C[row * N + col] = Cvalue;
    }
}

