__global__ void square_matrix_mul_kernel(const float* A, const float* B, float* C, int N) {
    // Define the tile size for shared memory. A common choice for square matrices.
    const int TILE_SIZE = 32; 
    const int PADDED_TILE_SIZE = TILE_SIZE + 1; // Add padding to avoid bank conflicts

    // Declare shared memory for tiles of A and B. 
    // sA is TILE_SIZE x TILE_SIZE. sB has padding in the second dimension.
    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][PADDED_TILE_SIZE];

